using System.Text;
using System.Text.Json;

namespace Gojo.Experiments.QualitativeFrieze.Composition;

/// <summary>A view of supplied native constructions and recorded reads. SVG
/// layout, navigation and explanatory labels never establish a junction, route,
/// handwriting convention or mechanical support law.</summary>
public static class GlyphJointAtlasGallery
{
    public static void Write(string output, string json)
    {
        Directory.CreateDirectory(output);
        File.WriteAllText(Path.Combine(output, "index.html"), Page.Replace("@@DATA@@", json.Replace("<", "\\u003c")));
        using var document = JsonDocument.Parse(json);
        File.WriteAllText(Path.Combine(output, "README.md"), Markdown(document.RootElement));
    }

    private static string Markdown(JsonElement root)
    {
        var text = new StringBuilder();
        void P(string value = "") => text.AppendLine(value);
        P("# Glyph joints: one drawing, several constructions and uses"); P();
        P("This study keeps four questions separate: what is drawn, which sites are actually shared, how the pen visits the sections, and which routes a later use permits. It supplies capital letters and digits, alternative constructions, small route machines, and conditional support reads. It does not learn handwriting or infer the intended use from a picture."); P();
        P("An L can be a continuous bend or two attached pieces. Both can have the same ink and final connectivity. An H can be drawn left to right while its later bridge use permits travel both ways. The extra history or route law must be present; the glyph name does not supply it."); P();
        P("Open [the visual atlas](index.html). [Recorded data](results.json), [native glyph constructions](corpus.gojo), [native construction landmarks](construction.gojo), [native route machines](usage.gojo), and [native contextual reads](contexts.gojo) retain the experiment's different evidence surfaces."); P();
        P("## How to read the atlas"); P();
        P("1. Choose a glyph and compare its construction variants. Colored sections show pen strokes. Select one stroke to see its green start and red stop. A dashed relocation moves the pen to its next landmark; it does not draw a connection.");
        P("2. Examine a joint machine. Its lines show available structure; arrows show explicitly supplied routes. A probe records a move, a block, an unresolved choice, or incomplete evidence.");
        P("3. Change the contextual premises. Ground contacts and a load-position projection onto the chosen ground/reference are supplied relations. A projection inside their span is a geometric read, not a proof of physical stability."); P();
        P("## The small structural grammar"); P();
        P("| Surface | What is connected | What it does not imply |"); P("| --- | --- | --- |");
        P("| Section | Actual start and end sites, with the selected geometric evidence | A drawn crossing is not automatically a shared site. |");
        P("| Pen stroke | Ordered visits to actual sections, with a selected traversal direction | Drawing direction is not a one-way traffic law. |");
        P("| Construction landmark | A stroke start or stop refers to a site already exposed by earlier drawing, or to an explicitly supplied placement relation | A future section cannot provide evidence for an earlier move. |");
        P("| Joint | Several section ends refer to one actual site | Shared attachment alone does not choose a turn or split conserved flow. |");
        P("| Route | Exposed input, connected passage and destination | A route is not available merely because two lines touch in the image. |");
        P("| Conditional law | Input and control evidence select permitted route candidates | Several candidates are not several executed copies of one packet. |");
        P("| Contextual read | Shape, selected ground, contacts, load and projection basis | A positive geometric result does not supply stiffness, friction or mass distribution. |");
        P("| Selection | A read chooses which existing sections or evidence to inspect | Unselected is not zero magnitude, nonexistence, or a stopped physical flow. |"); P();
        P("ODV remains a low-resolution magnitude read: V = 0 means undetectable at its selected resolution, not removal. The atlas uses native connected relations for sites, history and route laws; it does not claim that one ODV word encodes an entire joint or introduces a new universal joint opcode."); P();
        P("## Glyph catalogue"); P();
        P("The baseline constructions follow the supplied teaching cards and the cited school-print guides, with noted choices where conventions differ. Variants distinguish other teaching conventions from authored construction experiments. Curve controls provide one illustrative geometry. Counts concern retained sections and shared endpoints, not every apparent shape in a drawing. Pen-stroke groups record drawing history; they do not supply material stiffness or bolt, hinge or weld laws."); P();
        P("The primary joint reading now follows construction history. A continuous corner in L differs from returning to an existing endpoint and attaching F's top bar. Starting at a known interior point and drawing outward differs from arriving at that point and stopping. The geometric tangent reading remains available alongside that history; it does not replace it."); P();
        foreach (var item in Items(root, "Corpus"))
        {
            P($"### {Cell(T(item, "Glyph"))} — {T(item, "Title")}"); P();
            P(T(item, "Construction")); P(); P(T(item, "Note")); P();
            if (Get(item, "SourceUrl").ValueKind == JsonValueKind.String && !string.IsNullOrWhiteSpace(T(item, "SourceUrl")))
            { P($"Teaching reference: [{T(item, "SourceTitle")}]({T(item, "SourceUrl")})."); P(); }
            var topology = Get(item, "Topology");
            P($"Variant `{T(item, "VariantId")}`. Components: {T(topology, "Components")}; free ends: {T(topology, "FreeEnds")}; branch sites: {T(topology, "Branches")}; independent cycles: {T(topology, "CycleRank")}; pen strokes: {T(topology, "PenStrokes")}; revisited sections: {T(topology, "RevisitedSections")}; complete read: {T(topology, "Complete")}."); P();
            P("| Stroke | Ordered section visits | Continuous | Closed |"); P("| --- | --- | --- | --- |");
            foreach (var stroke in Items(item, "Strokes"))
                P($"| {StrokeNumber(stroke, "Index")} | {string.Join(" → ", Items(stroke, "Visits").Select(v => "s" + T(v, "Section") + (B(v, "Reverse") ? " reversed" : "")))} | {T(stroke, "Continuous")} | {T(stroke, "Closed")} |");
            P(); P("#### Starts, stops and construction landmarks"); P();
            P("| Stroke | Start | Earlier ink at start | Stop | Earlier ink at stop |"); P("| --- | --- | --- | --- | --- |");
            foreach (var stroke in Items(Get(item, "ConstructionRead"), "Strokes"))
                P($"| {StrokeNumber(stroke, "Index")} | p{T(stroke, "StartSite")}: {Cell(T(stroke, "StartDescription"))} | {Cell(StrokeList(stroke, "StartSourceStrokes"))} | p{T(stroke, "EndSite")}: {Cell(T(stroke, "EndDescription"))} | {Cell(StrokeList(stroke, "EndSourceStrokes"))} |");
            P();
            foreach (var stroke in Items(Get(item, "ConstructionRead"), "Strokes"))
            {
                if (Get(stroke, "PlacementSourceStroke").ValueKind == JsonValueKind.Number)
                    P($"- Stroke {StrokeNumber(stroke, "Index")}: declared placement relative to p{T(stroke, "PlacementSourceSite")} on stroke {StrokeNumber(stroke, "PlacementSourceStroke")}, local offset ({Join(stroke, "PlacementOffset")}), parallel read {T(stroke, "ParallelToSource")}.");
                foreach (var evidence in Items(stroke, "Events"))
                    P($"- Stroke {StrokeNumber(stroke, "Index")}, p{T(evidence, "Site")}: {T(evidence, "Description")} Earlier incidence count: {T(evidence, "BeforeDegree")}; earlier source strokes: {StrokeList(evidence, "SourceStrokes")}.");
            }
            P(); P("| Section | Actual sites | Selected control words | Straight read |"); P("| --- | --- | --- | --- |");
            foreach (var section in Items(item, "Lines"))
                P($"| s{T(section, "Index")} | p{T(section, "StartSite")} → p{T(section, "EndSite")} | {string.Join(" → ", Items(section, "Controls").Select(p => "(" + T(p, "X") + ", " + T(p, "Y") + ")"))} | {T(section, "Straight")} |");
            P();
            P("| Site | Construction history read | Selected position | Incidences | Geometric tangent read | Opposed pairs | Cooriented pairs |"); P("| --- | --- | --- | --- | --- | --- | --- |");
            foreach (var site in Items(item, "Sites"))
            {
                var history = Items(Get(item, "ConstructionRead"), "Sites").FirstOrDefault(read => T(read, "Site") == T(site, "Index"));
                P($"| p{T(site, "Index")} | {Cell(Join(history, "Descriptions"))} | ({T(site, "X")}, {T(site, "Y")}) | {T(site, "Degree")} | {GeometryLabel(T(site, "Joint"))} | {T(site, "OpposedPairs")} | {T(site, "CoorientedPairs")} |");
            }
            P();
        }
        P("## Joint machines and actual probes"); P();
        P("The supplied native route and finite-law structures are executed. A choice remains a choice until enough control is supplied. One material packet is not duplicated into all possible exits. The report preserves incoming, accepted, blocked and remainder accounting. These transfers are atomic from input to output port. Interior sites certify path connectivity; this pass does not simulate travel time, impact or residence at those sites."); P();
        foreach (var item in Items(Get(root, "Usage"), "Cases"))
        {
            P($"### {T(item, "Title")}"); P(); P(T(item, "Construction")); P(); P(T(item, "Use")); P();
            P("| Route | Input | Passage | Output |"); P("| --- | --- | --- | --- |");
            foreach (var route in Items(item, "Routes")) P($"| {T(route, "Id")} | {T(route, "From")} | {Join(route, "Via")} | {T(route, "To")} |");
            P(); P("| Probe | Input / control | Candidates | Outcome | Incoming = accepted + blocked + remainder | Destination | Ownership preserved |"); P("| --- | --- | --- | --- | --- | --- | --- |");
            foreach (var probe in Items(item, "Probes"))
            {
                P($"| {T(probe, "Id")} | {Cell(T(probe, "Input") + " / " + Join(probe, "Controls"))} | {Cell(Join(probe, "Candidates"))} | {T(probe, "Outcome")} | {T(probe, "Incoming")} = {T(probe, "Accepted")} + {T(probe, "Blocked")} + {T(probe, "Remainder")} | {Cell(Join(probe, "Destinations"))} | {T(probe, "OwnershipPreserved")} |");
            }
            P(); foreach (var probe in Items(item, "Probes")) P($"- **{T(probe, "Id")}:** {T(probe, "Explanation")}");
            P(); P("Limit: " + T(item, "Limits")); P();
        }
        P("## Ground, support and a selected use"); P();
        P("These examples ask only where a supplied load position projects onto the chosen ground/reference, relative to an explicitly selected contact span. They do not infer actual contact from equal screen coordinates or certify mechanical stability. The same geometry can receive different contacts, a different load or a different ground frame."); P();
        foreach (var item in Items(Get(root, "Contexts"), "Cases"))
        {
            P($"### {T(item, "Title")}"); P(); P(T(item, "Construction")); P(); P(T(item, "Interpretation")); P();
            P($"Supplied contacts: {Items(item, "Contacts").Count()}; validated contacts: {T(item, "ContactCount")}; projection read: **{T(item, "ProjectionRead")}**; native evidence complete: {T(item, "NativeComplete")}."); P();
            P("Limit: " + T(item, "Limits")); P();
        }
        foreach (var limit in Items(Get(root, "Contexts"), "Limits")) P("- " + Display(limit));
        P();
        P("## A small vocabulary of possible uses"); P();
        P("These are proposed transfers of a connected mechanism, not assertions that a glyph means a particular object. The route experiments above exercise specific capabilities; the broader nouns still require further context."); P();
        foreach (var item in Items(Get(root, "Contexts"), "Transfers"))
        {
            P($"### {T(item, "Name")}"); P(); P($"Glyph hints: {JoinOrText(item, "Glyphs")}. {T(item, "Structure")}"); P();
            P("Use: " + T(item, "Use")); P(); P("Additional premises: " + T(item, "Needs")); P(); P("Limit: " + T(item, "Limit")); P();
        }
        P("## What this establishes, and what stays open"); P();
        P("The useful distinction is between an identical visible artifact and different connected histories or permissions. A shared endpoint can enable a bend, an attachment, a junction or a bridge under different laws. An independent crossing can look like a shared crossing. Different views can reuse the same section without creating a second material section."); P();
        P("This pass supplies fixtures and laws; it does not autonomously discover meanings, infer a person's handwriting plan, learn a noun vocabulary, or derive forces from line art. Flow probes use the declared finite packet model. Support examples are conditional geometric reads. A general workspace, mechanical settlement and learned choice of interpretation remain further work.");
        return text.ToString();
    }

    private static JsonElement Get(JsonElement item, string key) => item.ValueKind == JsonValueKind.Object && item.TryGetProperty(key, out var value) ? value : default;
    private static IEnumerable<JsonElement> Items(JsonElement item, string key) => Get(item, key).ValueKind == JsonValueKind.Array ? Get(item, key).EnumerateArray() : [];
    private static string T(JsonElement item, string key) => Display(Get(item, key));
    private static string Display(JsonElement item) => item.ValueKind switch { JsonValueKind.Undefined or JsonValueKind.Null => "unresolved", JsonValueKind.String => item.GetString() ?? "", _ => item.ToString() };
    private static bool B(JsonElement item, string key) => Get(item, key).ValueKind == JsonValueKind.True;
    private static string Join(JsonElement item, string key) => string.Join(", ", Items(item, key).Select(Display));
    private static string StrokeNumber(JsonElement item, string key) => Get(item, key).ValueKind == JsonValueKind.Number && Get(item, key).TryGetInt32(out var value) ? (value + 1).ToString() : "unresolved";
    private static string StrokeList(JsonElement item, string key) => Items(item, key).Any() ? string.Join(", ", Items(item, key).Select(value => (value.GetInt32() + 1).ToString())) : "none";
    private static string JoinOrText(JsonElement item, string key) => Get(item, key).ValueKind == JsonValueKind.Array ? Join(item, key) : T(item, key);
    private static string Cell(string text) => text.Replace("|", "\\|").Replace("\r", " ").Replace("\n", " ");
    private static string GeometryLabel(string label) => label == "bend" ? "corner geometry" : label;

    private const string Page = """
